<div class="page-heading"><div><span class="eyebrow"><?= te('RECRUITMENT / AI REVIEW') ?></span><h1><?= te('Better questions. Human decisions.') ?></h1><p class="sub"><?= te('Claude supports evidence review and message drafting. No automatic hiring decision or candidate ranking.') ?></p></div></div>
<?php if($error): ?><div class="flash err"><?= e($error) ?></div><?php endif; ?>
<form method="post" class="card"><?= csrf_field() ?><h2><?= te('Review job-relevant evidence') ?></h2><label><?= te('Application') ?></label><select name="application_id"><?php foreach($applications as $application): ?><option value="<?= (int)$application['id'] ?>"><?= e($application['full_name'].' · '.$application['title']) ?></option><?php endforeach; ?></select><label><?= te('Relevant qualifications, experience and answers') ?></label><textarea name="evidence" maxlength="12000" required placeholder="Include verified skills and work experience only. Omit names, contact details, age, medical records, identity documents and screening reports."></textarea><label><input name="reviewed_evidence" type="checkbox" style="width:auto" required><?= te('I reviewed this evidence and the approved basis for sending it to the configured AI provider.') ?></label><button class="btn"><?= te('Request AI review') ?></button></form>
<?php foreach($reviews as $review): $result=json_decode($review['review_json'],true); ?><section class="card"><h2><?= e($review['full_name']) ?></h2><p class="small muted"><?= e($review['model'].' · '.$review['created_at']) ?></p><p><?= e($result['summary']) ?></p><div class="grid g3"><?php foreach(['matched_requirements'=>'Documented qualifications','missing_evidence'=>'Information to verify','screening_questions'=>'Suggested questions'] as $key=>$label): ?><div><h2><?= e($label) ?></h2><?php foreach($result[$key] as $item): ?><p><?= e($item) ?></p><?php endforeach; ?></div><?php endforeach; ?></div><h2><?= te('Draft message · review before use') ?></h2><p><?= nl2br(e($result['draft_message'])) ?></p><p class="muted"><?= te('This draft has not been sent. Provider messaging integrations and an approved communication workflow are required for external replies.') ?></p></section><?php endforeach; ?>
